import java.util.*;

class Graph {
    private final int n;
    private final List<int[]>[] adj;

    public Graph(int n, int[][] edges) {
        this.n = n;
        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            adj[edge[0]].add(new int[]{edge[1], edge[2]});
        }
    }

    public void addEdge(int[] edge) {
        adj[edge[0]].add(new int[]{edge[1], edge[2]});
    }

    public int shortestPath(int node1, int node2) {
        if (node1 == node2) {
            return 0;
        }
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[node1] = 0;
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
        heap.offer(new int[]{node1, 0});

        while (!heap.isEmpty()) {
            int[] current = heap.poll();
            int node = current[0];
            int cost = current[1];
            if (cost != dist[node]) {
                continue;
            }
            if (node == node2) {
                return cost;
            }
            for (int[] edge : adj[node]) {
                int next = edge[0];
                int nextCost = cost + edge[1];
                if (nextCost < dist[next]) {
                    dist[next] = nextCost;
                    heap.offer(new int[]{next, nextCost});
                }
            }
        }
        return -1;
    }
}

import java.util.*;

class Graph {
    private static final int INF = 1_000_000_000;
    private final int n;
    private final int[][] cost;

    public Graph(int n, int[][] edges) {
        this.n = n;
        cost = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(cost[i], INF);
            cost[i][i] = 0;
        }
        for (int[] edge : edges) {
            cost[edge[0]][edge[1]] = edge[2];
        }
    }

    public void addEdge(int[] edge) {
        cost[edge[0]][edge[1]] = edge[2];
    }

    public int shortestPath(int node1, int node2) {
        int[] dist = new int[n];
        boolean[] used = new boolean[n];
        Arrays.fill(dist, INF);
        dist[node1] = 0;

        for (int step = 0; step < n; step++) {
            int node = -1;
            for (int candidate = 0; candidate < n; candidate++) {
                if (!used[candidate] && (node == -1 || dist[candidate] < dist[node])) {
                    node = candidate;
                }
            }
            if (node == -1 || dist[node] == INF) {
                break;
            }
            if (node == node2) {
                return dist[node];
            }
            used[node] = true;
            for (int next = 0; next < n; next++) {
                if (cost[node][next] != INF && dist[node] + cost[node][next] < dist[next]) {
                    dist[next] = dist[node] + cost[node][next];
                }
            }
        }
        return dist[node2] == INF ? -1 : dist[node2];
    }
}

import java.util.*;

class Graph {
    private static final int INF = 1_000_000_000;
    private final int n;
    private final int[][] dist;

    public Graph(int n, int[][] edges) {
        this.n = n;
        dist = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
        }
        for (int[] edge : edges) {
            dist[edge[0]][edge[1]] = Math.min(dist[edge[0]][edge[1]], edge[2]);
        }
        for (int mid = 0; mid < n; mid++) {
            for (int from = 0; from < n; from++) {
                if (dist[from][mid] == INF) {
                    continue;
                }
                for (int to = 0; to < n; to++) {
                    if (dist[mid][to] != INF && dist[from][mid] + dist[mid][to] < dist[from][to]) {
                        dist[from][to] = dist[from][mid] + dist[mid][to];
                    }
                }
            }
        }
    }

    public void addEdge(int[] edge) {
        int u = edge[0];
        int v = edge[1];
        int w = edge[2];
        if (w >= dist[u][v]) {
            return;
        }
        for (int from = 0; from < n; from++) {
            if (dist[from][u] == INF) {
                continue;
            }
            for (int to = 0; to < n; to++) {
                if (dist[v][to] == INF) {
                    continue;
                }
                int candidate = dist[from][u] + w + dist[v][to];
                if (candidate < dist[from][to]) {
                    dist[from][to] = candidate;
                }
            }
        }
    }

    public int shortestPath(int node1, int node2) {
        return dist[node1][node2] == INF ? -1 : dist[node1][node2];
    }
}

import java.util.*;

class Graph {
    private static final int INF = 1_000_000_000;
    private final int n;
    private final List<int[]> edges = new ArrayList<>();

    public Graph(int n, int[][] edges) {
        this.n = n;
        for (int[] edge : edges) {
            this.edges.add(new int[]{edge[0], edge[1], edge[2]});
        }
    }

    public void addEdge(int[] edge) {
        edges.add(new int[]{edge[0], edge[1], edge[2]});
    }

    public int shortestPath(int node1, int node2) {
        int[] dist = new int[n];
        Arrays.fill(dist, INF);
        dist[node1] = 0;

        for (int pass = 0; pass < n - 1; pass++) {
            boolean changed = false;
            for (int[] edge : edges) {
                int from = edge[0];
                int to = edge[1];
                int weight = edge[2];
                if (dist[from] != INF && dist[from] + weight < dist[to]) {
                    dist[to] = dist[from] + weight;
                    changed = true;
                }
            }
            if (!changed) {
                break;
            }
        }
        return dist[node2] == INF ? -1 : dist[node2];
    }
}

import java.util.*;

class Graph {
    private final int n;
    private final List<int[]>[] adj;
    private final Map<Integer, int[]> distanceCache = new HashMap<>();

    public Graph(int n, int[][] edges) {
        this.n = n;
        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            adj[edge[0]].add(new int[]{edge[1], edge[2]});
        }
    }

    public void addEdge(int[] edge) {
        adj[edge[0]].add(new int[]{edge[1], edge[2]});
        distanceCache.clear();
    }

    public int shortestPath(int node1, int node2) {
        int[] dist = distanceCache.computeIfAbsent(node1, this::runDijkstraFrom);
        return dist[node2] == Integer.MAX_VALUE ? -1 : dist[node2];
    }

    private int[] runDijkstraFrom(int source) {
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
        heap.offer(new int[]{source, 0});

        while (!heap.isEmpty()) {
            int[] current = heap.poll();
            int node = current[0];
            int cost = current[1];
            if (cost != dist[node]) {
                continue;
            }
            for (int[] edge : adj[node]) {
                int next = edge[0];
                int nextCost = cost + edge[1];
                if (nextCost < dist[next]) {
                    dist[next] = nextCost;
                    heap.offer(new int[]{next, nextCost});
                }
            }
        }
        return dist;
    }
}
